(() => {
 const panel=document.querySelector('#stack-panel'),detail=document.querySelector('.stack-detail'),small=matchMedia('(max-width:700px)'),reduced=matchMedia('(prefers-reduced-motion: reduce)');
 const nodes=[
 ['react','React','⚛',14,18,'frontend','Interfaces et composants réactifs.'],['js','JavaScript','JS',29,26,'frontend','Logique applicative et interactions du navigateur.'],['ts','TypeScript','TS',13,35,'frontend','Typage et organisation des applications JavaScript.'],['html','HTML','5',29,43,'frontend','Structure sémantique de l’interface.'],['css','CSS','#',12,51,'frontend','Présentation et interfaces adaptatives.'],
 ['java','Java','J',77,16,'backend','Logique métier et applications Java.'],['spring','Spring Boot','S',85,31,'backend','Services et applications backend dans l’écosystème Java.'],['django','Django','dj',68,42,'backend','Applications web et services Python.'],['node','Node.js','N',87,51,'backend','Exécution JavaScript côté serveur.'],
 ['rest','REST API','↔',48,30,'api','Contrats et échanges entre client et services.'],['json','JSON','{}',48,48,'api','Format de données partagé entre les couches.'],['auth','Authentication','⌁',49,14,'api','Identité, accès et protection des ressources.'],
 ['mysql','MySQL','≋',68,77,'database','Stockage relationnel et requêtes SQL.'],['postgres','PostgreSQL','P',86,70,'database','Données relationnelles et requêtes structurées.'],['mongo','MongoDB','M',85,88,'database','Stockage et échanges de documents.'],
 ['docker','Docker','▱',47,80,'tools','Conteneurs et environnements reproductibles.'],['git','Git','⑂',13,77,'tools','Historique et suivi des modifications.'],['github','GitHub','GH',29,88,'tools','Hébergement des dépôts et collaboration.'],['maven','Maven','m',29,67,'tools','Dépendances et construction des projets Java.']
 ];
 const links=[['react','js'],['react','ts'],['react','rest'],['js','html'],['html','css'],['js','rest'],['ts','rest'],['rest','json'],['rest','auth'],['auth','spring'],['rest','spring'],['rest','django'],['rest','node'],['java','spring'],['spring','postgres'],['django','mysql'],['django','postgres'],['node','mongo'],['node','postgres'],['json','node'],['spring','docker'],['django','docker'],['postgres','docker'],['docker','git'],['git','github'],['github','docker'],['maven','java'],['maven','spring']];
 const route=['react','rest','spring','postgres'];
 panel.classList.add('engineering-map');detail.classList.add('map-detail');detail.textContent='Approchez une technologie pour explorer ses connexions. Au clavier : Tab puis Entrée. Sur mobile : touchez un nœud.';
 panel.innerHTML='<div class="map-topline"><span>ENGINEERING ECOSYSTEM / 01</span><div class="map-controls"><button class="map-reset" type="button">Réinitialiser ↺</button><button class="map-motion" type="button" aria-pressed="false">Pause des flux Ⅱ</button></div></div><div class="ecosystem-board" role="group" aria-label="Carte des technologies et de leurs connexions"><svg class="ecosystem-lines" aria-hidden="true"></svg></div><div class="map-bottomline"><span><i></i>CLIENT → SERVICES → DATA → DELIVERY</span><span class="map-selection">19 NODES / 05 ZONES</span></div>';
 const board=panel.querySelector('.ecosystem-board'),svg=panel.querySelector('svg'),status=panel.querySelector('.map-selection'),ns='http://www.w3.org/2000/svg';
 const groups=[['frontend','FRONTEND',5,6,2],['backend','BACKEND',67,5,25],['api','API & COMMUNICATION',38,4,42],['database','DATABASE',65,62,59],['tools','DEVOPS & TOOLS',5,61,77]];
 const zones=groups.map(([id,label,x,y,my])=>{const el=document.createElement('span');el.className='ecosystem-zone';el.textContent=label;board.append(el);return {id,el,x,y,my}});
 const buttons=new Map();nodes.forEach(([id,label,icon,x,y,group,description],i)=>{const b=document.createElement('button');b.type='button';b.className='ecosystem-node';b.dataset.node=id;b.setAttribute('aria-pressed','false');b.setAttribute('aria-label',`${label} — ${description} Explorer les connexions`);b.innerHTML=`<span class="ecosystem-icon" aria-hidden="true">${icon}</span><span>${label}</span>`;b.style.setProperty('--node-depth',String([1,.97,1.02][i%3]));board.append(b);buttons.set(id,b)});
 const paths=links.map(([a,b],i)=>{const path=document.createElementNS(ns,'path'),pulse=document.createElementNS(ns,'path');path.classList.add('ecosystem-link');pulse.classList.add('ecosystem-pulse');pulse.setAttribute('pathLength','100');pulse.style.animationDelay=`${-i*.53}s`;if(i===2||i===10||i===14)pulse.classList.add('is-ambient');svg.append(path,pulse);return {a,b,path,pulse}});
 for(let i=0;i<9;i++){const p=document.createElement('i');p.className='map-dust';p.style.cssText=`left:${(i*37+9)%96}%;top:${(i*23+14)%95}%;animation-delay:${-i}s`;board.append(p)}
 let selected=null,locked=null,focusNode=null,pointerFrame=0,mx=0,my=0,inside=false;
 const descriptions=new Map(nodes.map(n=>[n[0],n]));
 function select(id){if(selected===id)return;selected=id;const neighbors=new Set();if(id)links.forEach(([a,b])=>{if(a===id)neighbors.add(b);if(b===id)neighbors.add(a)});const showRoute=id&&route.includes(id);
 buttons.forEach((b,key)=>{b.classList.toggle('is-active',key===id);b.classList.toggle('is-neighbor',neighbors.has(key)||(showRoute&&route.includes(key)&&key!==id));b.setAttribute('aria-pressed',String(key===locked))});
 paths.forEach(({a,b,path,pulse})=>{const direct=!!id&&(a===id||b===id),onRoute=showRoute&&route.includes(a)&&route.includes(b);[path,pulse].forEach(el=>{el.classList.toggle('is-connected',direct);el.classList.toggle('is-route',!direct&&onRoute)})});
 if(id){const n=descriptions.get(id);detail.textContent=`${n[1]} / ${n[6]}${showRoute?' Exemple de parcours : React → REST API → Spring Boot → PostgreSQL.':''}`;status.textContent=`${n[1].toUpperCase()} / ${neighbors.size} CONNEXIONS`}else{detail.textContent='Approchez une technologie pour explorer ses connexions. Au clavier : Tab puis Entrée. Sur mobile : touchez un nœud.';status.textContent='19 NODES / 05 ZONES'}
 }
 function layout(){const w=board.clientWidth,h=board.clientHeight,counts={};nodes.forEach(([id,label,icon,x,y,group])=>{if(small.matches){const i=counts[group]||0;counts[group]=i+1;const start={frontend:8,backend:31,api:48,database:65,tools:83}[group];x=i%2?74:26;y=start+Math.floor(i/2)*6}const b=buttons.get(id);b.style.setProperty('--node-x',`${x}%`);b.style.setProperty('--node-y',`${y}%`)});zones.forEach(({el,x,y,my})=>{el.style.setProperty('--zone-x',`${small.matches?5:x}%`);el.style.setProperty('--zone-y',`${small.matches?my:y}%`)});svg.setAttribute('viewBox',`0 0 ${w} ${h}`);
 const rect=board.getBoundingClientRect();paths.forEach(({a,b,path,pulse},i)=>{const ra=buttons.get(a).getBoundingClientRect(),rb=buttons.get(b).getBoundingClientRect(),x1=ra.left+ra.width/2-rect.left,y1=ra.top+ra.height/2-rect.top,x2=rb.left+rb.width/2-rect.left,y2=rb.top+rb.height/2-rect.top,bend=(i%2?1:-1)*Math.min(80,Math.abs(y2-y1)*.18+20);const d=`M ${x1} ${y1} C ${x1+(x2-x1)*.4+bend} ${y1+(y2-y1)*.2}, ${x2-(x2-x1)*.35+bend} ${y2-(y2-y1)*.18}, ${x2} ${y2}`;path.setAttribute('d',d);pulse.setAttribute('d',d);const secondary=small.matches&&[5,9,16,18,19,20,21,25,27].includes(i);path.classList.toggle('mobile-secondary',secondary);pulse.classList.toggle('mobile-secondary',secondary)});
 }
 function pointer(){pointerFrame=0;if(!inside||locked||focusNode)return;const r=board.getBoundingClientRect();board.style.setProperty('--map-x',`${mx-r.left}px`);board.style.setProperty('--map-y',`${my-r.top}px`);let nearest=null,distance=small.matches?0:80;buttons.forEach((b,id)=>{const v=b.getBoundingClientRect(),dx=Math.max(v.left-mx,0,mx-v.right),dy=Math.max(v.top-my,0,my-v.bottom),d=Math.hypot(dx,dy);if(d<distance){distance=d;nearest=id}});select(nearest)}
 board.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;inside=true;mx=e.clientX;my=e.clientY;if(!pointerFrame)pointerFrame=requestAnimationFrame(pointer)},{passive:true});board.addEventListener('pointerleave',()=>{inside=false;if(!locked&&!focusNode)select(null);board.style.removeProperty('--map-x');board.style.removeProperty('--map-y')});
 board.addEventListener('click',e=>{const b=e.target.closest('[data-node]');if(!b)return;locked=locked===b.dataset.node?null:b.dataset.node;selected=undefined;select(locked)});
 board.addEventListener('focusin',e=>{const b=e.target.closest('[data-node]');if(b&&b.matches(':focus-visible')){focusNode=b.dataset.node;select(focusNode)}});board.addEventListener('focusout',e=>{if(!board.contains(e.relatedTarget)){focusNode=null;if(!locked)select(null)}});
 function reset(){locked=focusNode=null;selected=undefined;select(null)}panel.querySelector('.map-reset').addEventListener('click',reset);panel.addEventListener('keydown',e=>{if(e.key==='Escape')reset()});
 const motion=panel.querySelector('.map-motion');motion.addEventListener('click',()=>{const paused=panel.classList.toggle('map-paused');motion.setAttribute('aria-pressed',String(paused));motion.textContent=paused?'Reprendre les flux ▶':'Pause des flux Ⅱ'});
 new IntersectionObserver(entries=>panel.classList.toggle('map-offscreen',!entries[0].isIntersecting)).observe(panel);document.addEventListener('visibilitychange',()=>panel.classList.toggle('map-offscreen',document.hidden));new ResizeObserver(layout).observe(board);small.addEventListener('change',layout);document.fonts.ready.then(layout);layout();
})();
